<script setup lang="ts">
import { bangkok, modelText, type Reservation, type CourierLeg, type Page, type Station, type CommandResult } from '~/utils/types'
import { ApiFailure } from '~/composables/useApi'
const props=defineProps<{ mode:'pickup'|'dropoff' }>()
const api=useApi();const {courier}=useSession();const reservations=ref<Reservation[]>([]);const legs=ref<CourierLeg[]>([]);const stations=ref<Station[]>([]);const loading=ref(false);const saving=ref(false);const error=ref<unknown>();const message=ref('');const operation=ref<CommandResult>();const cancelling=ref<Reservation>();const reason=ref('');const photoId=ref('');const physical=ref(false)
type Selection={ tracking_mode:string;document_id:string;route_step_id:string;expected_version:number;station_id:string;document_version?:number;reservation_id?:string;leg_id?:string }
const selected=ref<Selection>();const selectedItems=ref<Selection[]>([]);const choices=ref<string[]>([]);const photos=ref<string[]>(['']);const batchResult=ref<CommandResult>()
const chosenLegs=computed(()=>legs.value.filter(l=>choices.value.includes(l.document_id)))
const destination=computed(()=>chosenLegs.value[0]?.to_station_id)
function begin(items:Selection[]){if(!items.length)return;selectedItems.value=items;selected.value=items[0];conflicted.value=false;cancelling.value=undefined;photos.value=[''];photoId.value='';physical.value=false;error.value=undefined;message.value=''}
function pickupItems(r:Reservation,ids:string[]){begin(r.items.filter(i=>ids.includes(i.document_id)).map(i=>({tracking_mode:i.tracking_mode,document_id:i.document_id,route_step_id:i.route_step_id,expected_version:i.document_version,station_id:r.station_id,reservation_id:r.id})))}
function groupedDropoff(){begin(chosenLegs.value.map(l=>({tracking_mode:l.tracking_mode,document_id:l.document_id,route_step_id:l.to_step_id,expected_version:l.document_version,station_id:l.to_station_id,leg_id:l.id})))}
function addPhoto(){photos.value.push('');photoId.value=''}
function photoReady(index:number,id:string){photos.value[index]=id;photoId.value=photos.value.every(Boolean)?photos.value[0]||'':''}
function removePhoto(){photos.value.pop();photoReady(0,photos.value[0]||'')}
const conflicted=ref(false)
const label=(id:string)=>stations.value.find(s=>s.id===id)?.name||id
async function load(){if(!courier.value)return;loading.value=true;error.value=undefined;try{const all=await Promise.all([api.get<Page<Station>>('/stations'),props.mode==='pickup'?api.get<Page<Reservation>>('/courier/reservations'):api.get<Page<CourierLeg>>('/courier/legs')]);stations.value=all[0].items;if(props.mode==='pickup')reservations.value=(all[1] as Page<Reservation>).items;else legs.value=(all[1] as Page<CourierLeg>).items}catch(e){error.value=e}finally{loading.value=false}}
function openPickup(r:Reservation,id:string){pickupItems(r,[id])}
function openDropoff(leg:CourierLeg){begin([{tracking_mode:leg.tracking_mode,document_id:leg.document_id,route_step_id:leg.to_step_id,expected_version:leg.document_version,station_id:leg.to_station_id,leg_id:leg.id}])}
async function submit(){const item=selected.value;if(!item||!photoId.value||conflicted.value||(props.mode==='pickup'&&!physical.value))return;saving.value=true;error.value=undefined;try{const body={station_id:item.station_id,items:selectedItems.value.map(i=>({document_id:i.document_id,route_step_id:i.route_step_id,expected_version:i.expected_version,...(i.leg_id?{leg_id:i.leg_id}:{})})),evidence_upload_ids:photos.value.filter(Boolean),...(props.mode==='pickup'?{reservation_id:item.reservation_id,physical_presence_confirmed:physical.value}:{})};const result=await api.command<CommandResult>(`/courier/${props.mode==='pickup'?'check-receive':'check-dropoff'}`,body);batchResult.value=result;operation.value=result.process_sync_status==='APPLIED'?undefined:result;choices.value=[];selected.value=undefined;message.value=!result.document_ids.length?'ไม่มีเรื่องที่ดำเนินการสำเร็จ โปรดดูเหตุผลและโหลดล่าสุด':props.mode==='pickup'?`บันทึกรับหนังสือจริง ${result.document_ids.length} เรื่องแล้ว เปิดช่วงนำส่งของคุณ`:`บันทึกรายงานส่งถึง ${result.document_ids.length} เรื่องแล้ว เรื่องใน Model B ยังต้องให้หน่วยงานยืนยันรับ ส่วน Model A บันทึกการนำส่งตามเส้นทาง`;await load()}catch(e){error.value=e;conflicted.value=e instanceof ApiFailure&&e.status===409}finally{saving.value=false}}
async function cancel(){if(!cancelling.value)return;saving.value=true;error.value=undefined;try{await api.command(`/courier/reservations/${cancelling.value.id}?expected_version=${cancelling.value.version}`,{reason:reason.value.trim()},'DELETE');cancelling.value=undefined;reason.value='';message.value='ยกเลิกการจองแล้ว';await load()}catch(e){error.value=e}finally{saving.value=false}}
async function refresh(){choices.value=[];selected.value=undefined;cancelling.value=undefined;conflicted.value=false;await load()}
onMounted(load)
</script>
<template><div class="page-head"><div><h1>{{mode==='pickup'?'การจองของฉัน':'งานนำส่งของฉัน'}}</h1><p>{{mode==='pickup'?'ตรวจหนังสือที่อยู่ตรงหน้าและยืนยันรูปก่อน Check รับ การจองยังไม่เปลี่ยนผู้ถือครอง':'แสดงเฉพาะช่วงนำส่งที่คุณรับผิดชอบ Check ส่งที่ปลายทางตามเส้นทางพร้อมรูปจริง'}}</p></div><div class="actions"><NuxtLink class="button" :to="mode==='pickup'?'/legs':'/reservations'">{{mode==='pickup'?'งานนำส่งของฉัน':'การจองของฉัน'}}</NuxtLink><button type="button" class="button" :disabled="loading||saving" @click="refresh">โหลดล่าสุด</button></div></div><Feedback v-if="!courier" :error="new Error('บัญชีนี้ไม่มีสิทธิ์ Courier')" /><template v-else><Feedback :error="error" :message="message" /><BatchResult :result="batchResult" @refresh="refresh" /><OperationStatus v-if="operation" :operation-id="operation.operation_id" :sync-status="operation.process_sync_status" @applied="operation=undefined;load()" /><section class="panel"><div v-if="mode==='dropoff'&&legs.length" class="actions"><button type="button" data-testid="bulk-dropoff-open" class="button primary" :disabled="saving||!!operation||!chosenLegs.length" @click="groupedDropoff">ตรวจปลายทางและ Check ส่ง {{chosenLegs.length}} เรื่อง</button><p class="hint">เลือกส่งรวมเฉพาะปลายทางเดียวกัน</p></div><UProgress v-if="loading" /><div v-if="!(mode==='pickup'?reservations.length:legs.length)&&!loading" class="empty"><h2>{{mode==='pickup'?'ไม่มีการจองที่ใช้งานอยู่':'ไม่มีช่วงนำส่งที่กำลังรับผิดชอบ'}}</h2><NuxtLink class="text-link" to="/worklist">เลือกหนังสือจากคิวรับของ Courier</NuxtLink></div><template v-if="mode==='pickup'"><article v-for="r in reservations" :key="r.id" class="work-entry"><div class="actions"><StatusTag :value="r.status" /><p>หมดอายุ {{bangkok(r.expires_at)}}</p></div><h2 class="entry-heading">รับจาก {{label(r.station_id)}}</h2><div v-for="item in r.items" :key="item.document_id"><label class="confirmation"><input v-model="choices" type="checkbox" :value="item.document_id" :aria-label="`เลือกรับหนังสือ ${item.document_id}`" :disabled="saving||!!operation||item.process_sync_status!=='APPLIED'" />หนังสืออ้างอิง {{item.document_id}}</label><div class="actions"><StatusTag :value="item.business_state" /><StatusTag :value="item.process_sync_status" /></div><p class="hint">{{modelText(item.tracking_mode)}}{{item.tracking_mode==='MODEL_A'?' · ต้องพบและถือหนังสือจริง ไม่ใช้ Unit READY':''}}</p><button v-if="r.status==='ACTIVE'" type="button" :data-testid="`pickup-open-${item.document_id}`" class="button primary actions" :disabled="saving||!!operation||item.process_sync_status!=='APPLIED'" @click="openPickup(r,item.document_id)">ตรวจหนังสือและ Check รับ</button><p v-if="item.process_sync_status!=='APPLIED'" class="hint">รอ workflow ประสานก่อน Check รับ</p></div><button v-if="r.items.length>1" type="button" data-testid="bulk-pickup-open" class="button primary actions" :disabled="saving||!!operation||!r.items.some(i=>choices.includes(i.document_id))" @click="pickupItems(r,choices)">ตรวจและ Check รับ {{r.items.filter(i=>choices.includes(i.document_id)).length}} เรื่องที่เลือก</button><button v-if="r.status==='ACTIVE'" type="button" class="button actions" :disabled="saving||!!operation" @click="cancelling=r;selected=undefined;reason=''">ยกเลิกการจอง</button></article></template><template v-else><article v-for="leg in legs" :key="leg.id" class="work-entry"><label class="confirmation"><input v-model="choices" type="checkbox" :value="leg.document_id" :aria-label="`เลือกส่งหนังสือ ${leg.document_id}`" :disabled="saving||!!operation||leg.process_sync_status!=='APPLIED'||!!destination&&destination!==leg.to_station_id" />นำส่งไป {{label(leg.to_station_id)}}</label><p>จาก {{label(leg.from_station_id)}}</p><p class="hint">รับจริงเมื่อ {{bangkok(leg.started_at)}}</p><p class="break">หนังสืออ้างอิง {{leg.document_id}}</p><div class="actions"><StatusTag value="IN_TRANSIT" /><StatusTag :value="leg.process_sync_status" /></div><p class="hint">{{modelText(leg.tracking_mode)}}</p><button type="button" :data-testid="`dropoff-open-${leg.document_id}`" class="button primary actions" :disabled="saving||!!operation||leg.process_sync_status!=='APPLIED'" @click="openDropoff(leg)">ตรวจปลายทางและ Check ส่ง</button><p v-if="leg.process_sync_status!=='APPLIED'" class="hint">รอ workflow ประสานก่อน Check ส่ง</p></article></template></section><form v-if="selected" class="panel" @submit.prevent="submit"><h2>{{mode==='pickup'?'ยืนยันรับหนังสือจริง':'ยืนยันส่งถึงปลายทาง'}}</h2><p>ตรวจรายชื่อและจำนวน {{selectedItems.length}} เรื่องก่อนยืนยัน รูปนี้จะเป็นหลักฐานร่วมของทุกเรื่องในชุด</p><ul><li v-for="item in selectedItems" :key="item.document_id" class="break">หนังสือ {{item.document_id}} · {{modelText(item.tracking_mode)}}</li></ul><p class="hint">{{mode==='pickup'?'Station รับ':'Station ปลายทาง'}}: {{label(selected.station_id)}}</p><EvidencePhoto v-for="(_,index) in photos" :key="`${selected.document_id}:${selected.leg_id||selected.reservation_id}:${index}`" :station-id="selected.station_id" :disabled="saving" @ready="photoReady(index,$event)" @changed="photoReady(index,'')" /><button type="button" class="button" :disabled="saving||photos.length>=5" @click="addPhoto">แนบภาพเพิ่ม</button><button v-if="photos.length>1" type="button" class="button" :disabled="saving" @click="removePhoto">นำช่องภาพสุดท้ายออก</button><label v-if="mode==='pickup'" class="confirmation"><input v-model="physical" data-testid="physical-presence" type="checkbox" :disabled="saving" />ฉันตรวจรายชื่อ จำนวน และถือหนังสือจริงที่เลือกครบแล้ว</label><p v-else-if="selected.tracking_mode==='MODEL_B'" class="hint">Check ส่งเป็นรายงานของ Courier หน่วยงานต้องยืนยันรับแยกต่างหาก หนังสือคืนต้นทางจะเสร็จเมื่อยืนยันรับคืน</p><p v-else class="hint">Model A บันทึกเฉพาะหลักฐานของ Courier ไม่มีการยืนยันรับจากหน่วยงาน จุดสุดท้ายจบเป็น “ติดตามการนำส่งครบแล้ว” ไม่ใช่การรับคืนที่หน่วยงานยืนยัน</p><div class="actions"><button :data-testid="mode==='pickup'?'courier-pickup':'courier-dropoff'" class="button primary" :disabled="saving||conflicted||!photoId||(mode==='pickup'&&!physical)">{{saving?'กำลังบันทึก…':mode==='pickup'?'ยืนยัน Check รับ':'ยืนยัน Check ส่ง'}}</button><button type="button" class="button" :disabled="saving" @click="selected=undefined">กลับ</button></div><p v-if="error" class="hint">ข้อมูลและรูปยังอยู่ หากข้อมูลชนกัน ให้โหลดล่าสุดและตรวจรายการอีกครั้งก่อนยืนยัน</p></form><form v-if="cancelling" class="panel" @submit.prevent="cancel"><h2>ยกเลิกการจอง</h2><div class="field"><label for="cancel-reason">เหตุผล</label><textarea id="cancel-reason" v-model="reason" required maxlength="1000" /></div><div class="actions"><button class="button danger" :disabled="saving">{{saving?'กำลังยกเลิก…':'ยืนยันยกเลิกการจอง'}}</button><button class="button" type="button" :disabled="saving" @click="cancelling=undefined">กลับ</button></div></form></template></template>
